/**
 * Capitalizes the first letter of each word in a given sentence.
 * 
 * @param {string} sentence The input string to be capitalized.
 * @returns {string} The sentence with each word capitalized.
 */
function capitalizeWords(sentence) {
  if (!sentence || typeof sentence !== 'string') {
    return "";
  }

  // 1. Convert the entire sentence to lowercase to handle mixed-case input consistently.
  const lowerCaseSentence = sentence.toLowerCase();

  // 2. Split the sentence into an array of words using spaces as the delimiter.
  const words = lowerCaseSentence.split(' ');

  // 3. Map over the array of words, capitalizing the first letter of each word.
  const capitalizedWords = words.map(word => {
    // Handle empty strings that might result from multiple spaces
    if (word.length === 0) {
      return '';
    }
    // Capitalize the first letter and concatenate the rest of the word.
    return word.charAt(0).toUpperCase() + word.slice(1);
  });

  // 4. Join the array of capitalized words back into a single string with spaces.
  const result = capitalizedWords.join(' ');

  return result;
}

