console.log(`\nOriginal: "${sentence2}"`);
console.log(`Capitalized: "${capitalizeWords(sentence2)}"`); // Output: "This Is A Mixed Case Sentence"

const sentence3 = "  leading and trailing spaces ";
console.log(`\nOriginal: "${sentence3}"`);
console.log(`Capitalized: "${capitalizeWords(sentence3)}"`); // Output: "  Leading And Trailing Spaces "
